import { EvidenceStore, hasMissingMetrics } from '../parsers/index-store.js';

/**
 * ATS schema types supported for parsing and analysis
 */
export type ATSSchema = 'greenhouse' | 'lever' | 'generic';

/**
 * Standard section headers expected by ATS systems
 * Includes common variations that should be recognized case-insensitively
 */
export const STANDARD_SECTIONS = [
  'Summary', 'Experience', 'Education', 'Skills', 'Projects', 
  'Certifications', 'Publications', 'Awards'
] as const;

export type ATSSchemaType = typeof STANDARD_SECTIONS[number];

/**
 * Types of issues detected by the ATS analyzer
 */
export type ATSIssueType = 
  | 'missing_section' 
  | 'multi_column_distortion' 
  | 'malformed_header' 
  | 'keyword_gap' 
  | 'parsing_anomaly';

/**
 * Represents a single ATS issue detected during analysis
 */
export interface ATSIssue {
  type: ATSIssueType;
  message: string;
  section?: string;
  severity: 'error' | 'warning';
  line?: number;
}

/**
 * Complete result of ATS analysis
 */
export interface ATSAnalysisResult {
  score: number; // 0-100
  band: 'excellent' | 'good' | 'fair' | 'poor';
  issues: ATSIssue[];
  sectionsFound: string[];
  sectionsMissing: string[];
  keywordMatches: number;
  keywordTotal: number;
  schema: ATSSchema;
}

/**
 * Parsed sections structure returned by ATS simulations
 */
export interface ParsedSections {
  headers: string[];
  sections: Map<string, string>;
  fullText: string;
}

/**
 * Keyword dictionaries for different ATS schemas
 */
export const ATS_KEYWORDS_GREENHOUSE = [
  'JavaScript', 'TypeScript', 'React', 'Node.js', 'Python', 'Java', 
  'AWS', 'Docker', 'Kubernetes', 'SQL', 'MongoDB', 'Git', 'CI/CD',
  'REST API', 'GraphQL', 'Microservices', 'Cloud', 'DevOps'
];

export const ATS_KEYWORDS_LEVER = [
  'Agile', 'Scrum', 'Kanban', 'JIRA', 'Confluence', 'Story Points',
  'Technical Debt', 'Code Review', 'Pair Programming', 'TDD', 'BDD',
  'User Stories', 'Sprint Planning', 'Retrospectives', 'Continuous Delivery'
];

export const ATS_KEYWORDS_GENERIC = [
  'Leadership', 'Communication', 'Problem Solving', 'Teamwork', 'Planning',
  'Organization', 'Analytical', 'Creative', 'Strategic', 'Adaptability',
  'Time Management', 'Project Management', 'Client Relations'
];

/**
 * Heuristic for multi-column distortion detection
 * Flags when bullet lines are unusually short (< 40 chars) suggesting column wrap
 */
function detectMultiColumnDistortion(text: string): boolean {
  const lines = text.split('\n');
  const shortBulletLines = lines.filter(line => {
    const trimmed = line.trim();
    return (
      trimmed.startsWith('•') || 
      trimmed.startsWith('-') || 
      trimmed.startsWith('*') ||
      (trimmed.includes('•') || trimmed.includes('-') || trimmed.includes('*'))
    ) && trimmed.length < 40 && trimmed.length > 0;
  });

  return shortBulletLines.length > Math.ceil(lines.length * 0.3);
}

/**
 * Extracts section headers from plain text
 * Looks for markdown-style headers (##, ###) or plain line-case headers
 */
function extractSectionHeaders(text: string): string[] {
  const lines = text.split('\n');
  const headers: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();

    // Markdown headers: ## Header or ### Header
    if (trimmed.match(/^#{2,3}\s+(.+)$/)) {
      headers.push(trimmed.replace(/^#{2,3}\s+/, ''));
    }
    // Plain headers in ALL CAPS or Title Case at start of line
    else if (/^[A-Z\s]{3,}$/.test(trimmed) && trimmed.length < 60) {
      // Filter out lines that look like navigation or metadata
      const lower = trimmed.toLowerCase();
      if (!['navigation', 'menu', 'home', 'about', 'contact', 'services'].includes(lower)) {
        headers.push(trimmed);
      }
    }
  }

  return headers;
}

/**
 * Computes keyword score by counting target keywords in text
 */
function computeKeywordScore(text: string, targetKeywords: string[]): { matches: number; total: number } {
  const lowerText = text.toLowerCase();
  let matches = 0;

  for (const keyword of targetKeywords) {
    const lowerKeyword = keyword.toLowerCase();
    if (lowerText.includes(lowerKeyword)) {
      matches++;
    }
  }

  return {
    matches,
    total: targetKeywords.length
  }
}

/**
 * Simulates Greenhouse ATS parsing behavior
 * Strict parsing focusing on standard section extraction
 */
function simulateGreenhouseParse(text: string): ParsedSections {
  const headers = extractSectionHeaders(text);
  const sections: Map<string, string> = new Map();

  // For Greenhouse, we look for standard sections more rigidly
  const lowerText = text.toLowerCase();

  for (const standardSection of STANDARD_SECTIONS) {
    const lowerStandard = standardSection.toLowerCase();

    // Look for the standard section in the text
    const index = lowerText.indexOf(lowerStandard);
    if (index !== -1) {
      // Extract a reasonable chunk after the section header
      const sectionText = text.substring(index, Math.min(index + 500, text.length));
      sections.set(standardSection, sectionText);
    }
  }

  return {
    headers,
    sections,
    fullText: text
  };
}

/**
 * Simulates Lever ATS parsing behavior
 * More tolerant of formatting, keyword-focused parsing
 */
function simulateLeverParse(text: string): ParsedSections {
  const headers = extractSectionHeaders(text);
  const sections: Map<string, string> = new Map();

  const lowerText = text.toLowerCase();

  // Lever tends to parse based on keywords and structure
  // More lenient matching for section identification
  const flexibleSections = [...STANDARD_SECTIONS, 
    'Experience', 'Work', 'Employment', 'Career', 
    'Technical Skills', 'Competencies', 'Abilities',
    'Professional Experience', 'Work History'
  ];

  for (const section of flexibleSections) {
    const lowerSection = section.toLowerCase();
    const index = lowerText.indexOf(lowerSection);
    if (index !== -1) {
      const sectionText = text.substring(index, Math.min(index + 400, text.length));
      sections.set(section, sectionText);
    }
  }

  return {
    headers,
    sections,
    fullText: text
  };
}

/**
 * Generic ATS parser for unknown ATS systems
 */
function simulateGenericParse(text: string): ParsedSections {
  const headers = extractSectionHeaders(text);
  const sections: Map<string, string> = new Map();

  // Generic parser - simpler, more forgiving
  const lines = text.split('\n');
  let currentSection = 'Unknown';
  let sectionContent: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.match(/^#{2,3}\s+(.+)$/)) {
      // Save previous section
      if (sectionContent.length > 0 && currentSection !== 'Unknown') {
        sections.set(currentSection, sectionContent.join(' '));
      }
      // Start new section
      currentSection = trimmed.replace(/^#{2,3}\s+/, '');
      sectionContent = [];
    } else if (trimmed.length > 0) {
      sectionContent.push(trimmed);
    }
  }

  // Save last section
  if (sectionContent.length > 0 && currentSection !== 'Unknown') {
    sections.set(currentSection, sectionContent.join(' '));
  }

  return {
    headers,
    sections,
    fullText: text
  };
}

/**
 * Main ATS analysis function
 * Analyzes resume text against specified ATS schema
 */
export function analyzeATS(text: string, schema: ATSSchema = 'greenhouse', targetKeywords?: string[]): ATSAnalysisResult {
  // Handle empty input
  if (!text || text.trim().length === 0) {
    return {
      score: 0,
      band: 'poor',
      issues: [
        {
          type: 'parsing_anomaly',
          message: 'Empty or whitespace-only input',
          severity: 'error'
        }
      ],
      sectionsFound: [],
      sectionsMissing: STANDARD_SECTIONS,
      keywordMatches: 0,
      keywordTotal: targetKeywords?.length || ATS_KEYWORDS_GREENHOUSE.length,
      schema
    };
  }

  // Get schema-specific keywords
  const schemaKeywords = 
    schema === 'greenhouse' ? ATS_KEYWORDS_GREENHOUSE :
    schema === 'lever' ? ATS_KEYWORDS_LEVER :
    ATS_KEYWORDS_GENERIC;

  // Use provided targetKeywords or schema defaults
  const keywordsToUse = targetKeywords || schemaKeywords;
  const keywordScore = computeKeywordScore(text, keywordsToUse);

  // Detect multi-column distortion
  const hasMultiColumn = detectMultiColumnDistortion(text);

  // Get appropriate parser based on schema
  let parsedSections: ParsedSections;
  switch (schema) {
    case 'greenhouse':
      parsedSections = simulateGreenhouseParse(text);
      break;
    case 'lever':
      parsedSections = simulateLeverParse(text);
      break;
    default:
      parsedSections = simulateGenericParse(text);
  }

  // Normalize and validate sections found
  const sectionsFound: string[] = [];
  const sectionsMissing: string[] = [];

  // Case-insensitive comparison against standard sections
  const normalizedText = text.toLowerCase();
  for (const standardSection of STANDARD_SECTIONS) {
    const lowerStandard = standardSection.toLowerCase();
    if (normalizedText.includes(lowerStandard)) {
      sectionsFound.push(standardSection);
    } else {
      sectionsMissing.push(standardSection);
    }
  }

  // Build issues array
  const issues: ATSIssue[] = [];

  // Add missing section issues
  for (const missingSection of sectionsMissing) {
    issues.push({
      type: 'missing_section',
      message: `Missing standard section: ${missingSection}`, 
      section: missingSection,
      severity: 'error'
    });
  }

  // Add multi-column distortion warning
  if (hasMultiColumn) {
    issues.push({
      type: 'multi_column_distortion',
      message: 'Multi-column distortion detected - short bullet lines suggest column wrap',
      severity: 'warning'
    });
  }

  // Add malformed header issues
  for (const header of parsedSections.headers) {
    // Check for headers that don't follow expected patterns
    if (header.match(/^[A-Z]{2,}$/) && header.length > 60) {
      issues.push({
        type: 'malformed_header',
        message: `Potentially malformed header: ${header}`, 
        section: header,
        severity: 'warning'
      });
    }
  }

  // Add keyword gap warning if coverage is low
  const keywordCoverage = keywordScore.total > 0 ? (keywordScore.matches / keywordScore.total) : 0;
  if (keywordCoverage < 0.5) {
    issues.push({
      type: 'keyword_gap',
      message: `Low keyword coverage: ${keywordScore.matches}/${keywordScore.total} keywords matched`, 
      severity: 'warning'
    });
  }

  // Calculate comprehensive score (0-100)
  let score = 0;

  // Section weight: 40% of total score
  if (sectionsFound.length > 0) {
    const sectionScore = (sectionsFound.length / STANDARD_SECTIONS.length) * 100 * 0.4;
    score += sectionScore;
  }

  // Keyword weight: 30% of total score  
  if (keywordScore.total > 0) {
    const keywordScoreValue = (keywordScore.matches / keywordScore.total) * 100 * 0.3;
    score += keywordScoreValue;
  }

  // Parsing cleanliness weight: 20% of total score
  // Deduct for issues found
  const totalIssueWeight = issues.length * 5; // Each issue reduces score by 5 points
  const cleanlinessScore = Math.max(0, 100 - totalIssueWeight) * 0.2;
  score += cleanlinessScore;

  // Structure weight: 10% of total score
  const structureScore = headers.length > 0 ? Math.min(headers.length * 5, 50) * 0.1 : 0;
  score += structureScore;

  // Ensure score is within bounds
  score = Math.max(0, Math.min(100, score));

  // Determine score band
  let band: 'excellent' | 'good' | 'fair' | 'poor';
  if (score >= 85) {
    band = 'excellent';
  } else if (score >= 70) {
    band = 'good';
  } else if (score >= 50) {
    band = 'fair';
  } else {
    band = 'poor';
  }

  return {
    score: Math.round(score),
    band,
    issues,
    sectionsFound,
    sectionsMissing,
    keywordMatches: keywordScore.matches,
    keywordTotal: keywordScore.total,
    schema
  };
}

/**
 * Convenience function for Greenhouse ATS analysis
 */
export function analyzeGreenhouseATS(text: string): ATSAnalysisResult {
  return analyzeATS(text, 'greenhouse');
}

/**
 * Convenience function for Lever ATS analysis
 */
export function analyzeLeverATS(text: string): ATSAnalysisResult {
  return analyzeATS(text, 'lever');
}

/**
 * Convenience function for Generic ATS analysis
 */
export function analyzeGenericATS(text: string): ATSAnalysisResult {
  return analyzeATS(text, 'generic');
}

