describe('ATS Simulation & Readability Gate', () => {
  it('analyzes complete Greenhouse ATS resume', () => {
    const text = [
      '# John Doe',
      '## Summary',
      'Software Engineer with 5 years experience in JavaScript and React.',
      '## Experience',
      '• Senior Developer at TechCorp (2020-2023)',
      '• Led migration to microservices architecture.',
      '## Education',
      'B.S. Computer Science, University of Technology (2016)',
      '## Skills',
      'JavaScript, TypeScript, React, Node.js, AWS, Docker, Kubernetes'
    ].join('\n');

    const result = analyzeATS(text, 'greenhouse');

    expect(result.score).toBeGreaterThanOrEqual(85);
    expect(result.band).toBe('excellent');
    expect(result.sectionsMissing).toHaveLength(0);
    expect(result.keywordMatches).toBeGreaterThan(0);
  });

  it('flags missing Experience section in Greenhouse ATS', () => {
    const text = [
      '# John Doe',
      '## Summary',
      'Software Engineer with 5 years experience.',
      '## Education',
      'B.S. Computer Science, University of Technology (2016)',
      '## Skills',
      'JavaScript, TypeScript, React, Node.js'
    ].join('\n');

    const result = analyzeATS(text, 'greenhouse');

    expect(result.score).toBeLessThan(70);
    expect(result.issues.some(issue => issue.type === 'missing_section' && issue.section === 'Experience')).toBe(true);
  });

  it('flags missing Education section in Greenhouse ATS', () => {
    const text = [
      '# John Doe',
      '## Summary',
      'Software Engineer with 5 years experience.',
      '## Experience',
      '• Senior Developer at TechCorp (2020-2023)',
      '## Skills',
      'JavaScript, TypeScript, React, Node.js'
    ].join('\n');

    const result = analyzeATS(text, 'greenhouse');

    expect(result.issues.some(issue => issue.type === 'missing_section' && issue.section === 'Education')).toBe(true);
  });

  it('computes Lever ATS keyword scoring', () => {
    const text = 'Scrum Master with Agile experience. Knowledge of JIRA and Confluence.';
    const targetKeywords = ['Agile', 'Scrum', 'JIRA', 'Confluence'];

    const result = analyzeATS(text, 'lever', targetKeywords);

    expect(result.keywordMatches).toBe(4);
    expect(result.keywordTotal).toBe(4);
  });

  it('detects multi-column distortion in ATS parsing', () => {
    const text = [
      '# Resume',
      '## Experience',
      '• Developer',
      '• Designer',
      '• Manager',
      'Short entry',
      '• QA',
      'Consultant'
    ].join('\n');

    const result = analyzeATS(text, 'greenhouse');

    expect(result.issues.some(issue => issue.type === 'multi_column_distortion')).toBe(true);
    expect(result.issues.find(issue => issue.type === 'multi_column_distortion')?.severity).toBe('warning');
  });

  it('detects malformed headers in ATS parsing', () => {
    const text = [
      '# Resume',
      '## SUMMARY', // Uppercase header
      '## EXPERIENCE', // Uppercase header
      'Some content'
    ].join('\n');

    const result = analyzeATS(text, 'greenhouse');

    expect(result.issues.some(issue => issue.type === 'malformed_header')).toBe(true);
  });

  it('handles case-insensitive section matching in Greenhouse ATS', () => {
    const text = [
      '# John Doe',
      '## WORK EXPERIENCE', // Mixed case
      '## EDUCATION', // Uppercase
      'Bachelor\'s degree in Computer Science'
    ].join('\n');

    const result = analyzeATS(text, 'greenhouse');

    expect(result.sectionsFound.length).toBeGreaterThanOrEqual(2);
    expect(result.sectionsFound.some(section => section.toLowerCase().includes('experience') || section.toLowerCase().includes('education'))).toBe(true);
  });

  it('handles empty/whitespace-only resume in ATS analysis', () => {
    const text = '';

    const result = analyzeATS(text, 'greenhouse');

    expect(result.score).toBe(0);
    expect(result.band).toBe('poor');
    expect(result.sectionsMissing).toEqual(['Summary', 'Experience', 'Education', 'Skills', 'Projects', 'Certifications', 'Publications', 'Awards']);
  });

  it('works correctly with different ATS schema parameters', () => {
    const text = [
      '# Test',
      '## Summary',
      'Test content'
    ].join('\n');

    const greenhouseResult = analyzeATS(text, 'greenhouse');
    const leverResult = analyzeATS(text, 'lever');
    const genericResult = analyzeATS(text, 'generic');
    const defaultResult = analyzeATS(text);

    expect(greenhouseResult.schema).toBe('greenhouse');
    expect(leverResult.schema).toBe('lever');
    expect(genericResult.schema).toBe('generic');
    expect(defaultResult.schema).toBe('greenhouse'); // default is 'greenhouse'
  });

  it('computes keyword score with custom target keywords', () => {
    const text = 'I have experience with Kubernetes and TypeScript, but not with Java or Python.';
    const targetKeywords = ['Kubernetes', 'TypeScript', 'Java', 'Python'];

    const result = analyzeATS(text, 'greenhouse', targetKeywords);

    expect(result.keywordMatches).toBe(2);
    expect(result.keywordTotal).toBe(4);
  });

  it('integrates with existing integrity functions without interference', () => {
    const text = [
      '# Test Resume',
      '## Summary',
      'Experience (ev-001) in software development.',
      '[METRIC NEEDED] for performance testing'
    ].join('\n');

    const lintResult = lintCitations(text, store);
    const metricsResult = validateMetrics(text, store);
    const deslopResult = auditSlop(text);
    const atsResult = analyzeATS(text, 'greenhouse');

    expect(lintResult.validCitations).toContain('ev-001');
    expect(metricsResult.issues.some(i => i.type === 'missing_metric')).toBe(true);
    expect(atsResult.score).toBeGreaterThan(0);
    expect(atsResult.score).toBeLessThan(100);
  });
});
